#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, p;
    if (!(cin >> s >> p)) return 0;
    int n = (int)s.size(), m = (int)p.size();

    // next[i]：p[0..next[i]-1] 与 p[i-next[i]..i-1] 相同的最长长度，next[0] = -1
    vector<int> nxt(m + 1);
    nxt[0] = -1;
    int i = 0, j = -1;
    while (i < m) {
        if (j == -1 || p[i] == p[j]) {
            i++;
            j++;
            nxt[i] = j;
        } else {
            j = nxt[j];
        }
    }

    i = 0; j = 0;
    while (i < n && j < m) {
        if (j == -1 || s[i] == p[j]) {
            i++;
            j++;
        } else {
            j = nxt[j];
        }
    }
    if (j >= m) cout << i - m << "\n";
    else cout << "no\n";
    return 0;
}
